import java.util.*;

class Solution {
    public int networkDelayTime(int[][] times, int n, int k) {
        final int INF = Integer.MAX_VALUE / 2;
        int[] dist = new int[n + 1];
        Arrays.fill(dist, INF);
        dist[k] = 0;

        for (int round = 1; round < n; round++) {
            boolean changed = false;
            for (int[] e : times) {
                int u = e[0], v = e[1], w = e[2];
                if (dist[u] != INF && dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    changed = true;
                }
            }
            if (!changed) break;
        }

        int best = 0;
        for (int i = 1; i <= n; i++) {
            if (dist[i] == INF) return -1;
            best = Math.max(best, dist[i]);
        }
        return best;
    }
}

import java.util.*;

class Solution {
    public int networkDelayTime(int[][] times, int n, int k) {
        final int INF = Integer.MAX_VALUE / 2;
        int[][] dist = new int[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            Arrays.fill(dist[i], INF);
            dist[i][i] = 0;
        }
        for (int[] e : times) {
            dist[e[0]][e[1]] = Math.min(dist[e[0]][e[1]], e[2]);
        }

        for (int mid = 1; mid <= n; mid++) {
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    int through = dist[i][mid] + dist[mid][j];
                    if (through < dist[i][j]) dist[i][j] = through;
                }
            }
        }

        int best = 0;
        for (int i = 1; i <= n; i++) {
            if (dist[k][i] == INF) return -1;
            best = Math.max(best, dist[k][i]);
        }
        return best;
    }
}

import java.util.*;

class Solution {
    public int networkDelayTime(int[][] times, int n, int k) {
        final int INF = Integer.MAX_VALUE / 2;
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (int[] e : times) adj.get(e[0]).add(new int[]{e[1], e[2]});

        int[] dist = new int[n + 1];
        Arrays.fill(dist, INF);
        dist[k] = 0;

        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        heap.add(new int[]{0, k});

        while (!heap.isEmpty()) {
            int[] top = heap.poll();
            int d = top[0];
            int u = top[1];
            if (d > dist[u]) continue;

            for (int[] nb : adj.get(u)) {
                int v = nb[0];
                int w = nb[1];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    heap.add(new int[]{dist[v], v});
                }
            }
        }

        int best = 0;
        for (int i = 1; i <= n; i++) {
            if (dist[i] == INF) return -1;
            best = Math.max(best, dist[i]);
        }
        return best;
    }
}
